'use strict';
const PROFILE_KEY='alinho-active-profile-v1';
let activeProfileId='';try{activeProfileId=localStorage.getItem(PROFILE_KEY)||''}catch{}
let sharedSupportsProfiles=false,profilePrompted=false;
function currentProfile(){return (state.profiles||[]).find(p=>p.id===activeProfileId)||null}
function profileInitials(name){const words=String(name||'').trim().split(/\s+/).filter(w=>w&&!['de','da','do','dos','das','e'].includes(w.toLowerCase()));return words.length?(words[0][0]+(words.length>1?words[words.length-1][0]:'')).toLocaleUpperCase('pt-BR'):''}
function profileAvatar(person,cls=''){return `<span class="avatar ${cls}" aria-hidden="true">${person?.photo?`<img src="${esc(person.photo)}" alt="">`:person?esc(profileInitials(person.name)):icon('user')}</span>`}
function profileControl(){const p=currentProfile();return `<button class="profile-control" type="button" data-profile-action="menu" aria-label="${p?'Perfil de '+esc(p.name):'Escolher meu perfil'}">${profileAvatar(p)}<span class="profile-copy"><strong>${p?esc(p.name):'Seu perfil'}</strong><small>${p?esc(p.title||'Equipe da empresa'):'Quem está usando?'}</small></span><svg class="profile-chevron" viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></button>`}
function selectProfile(id){activeProfileId=id;try{if(id)localStorage.setItem(PROFILE_KEY,id);else localStorage.removeItem(PROFILE_KEY)}catch{}closeModal();shell();if(id)toast('Perfil selecionado: '+currentProfile().name)}
function profileDialog(title,subtitle,body,footer=''){const m=document.getElementById('modal');m.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div>${btn('close',icon('close'),'','','','type="button" aria-label="Fechar"')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;m.showModal()}
function profileButton(action,text,extra='',primary=false){return `<button type="button" ${primary?'class="primary"':''} data-profile-action="${action}" ${extra}>${text}</button>`}
function requireProfiles(){if(sharedSupportsProfiles)return true;profileDialog('Ativar os perfis do Nova Aliança','A identidade visual já está pronta.',`<p class="full help">Feche o CMD do servidor e abra <strong>iniciar-lan.cmd</strong> novamente uma vez. Depois recarregue a página para criar os perfis da equipe. A frota cadastrada permanece salva.</p>`);return false}
function openProfilePicker(){if(!requireProfiles())return;const list=[...(state.profiles||[])].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));profileDialog('Quem está usando o Nova Aliança?','Cada pessoa tem seu perfil. A frota continua sendo da empresa.',`<div class="profile-list">${list.length?list.map(p=>`<button type="button" class="profile-row ${p.id===activeProfileId?'selected':''}" data-profile-action="select" data-id="${esc(p.id)}">${profileAvatar(p)}<span class="person-info"><strong>${esc(p.name)}</strong><small>${esc(p.title||'Equipe da empresa')}</small></span>${p.id===activeProfileId?icon('check'):icon('arrow')}</button>`).join(''):'<p class="help">Crie o primeiro perfil para identificar seus registros.</p>'}</div><p class="profile-footnote">A seleção fica lembrada neste navegador. Em um aparelho compartilhado, troque de pessoa antes de fazer registros.</p>`,profileButton('create',icon('plus')+' Criar meu perfil','',true))}
function openProfileMenu(){if(!requireProfiles())return;const p=currentProfile();if(!p)return openProfilePicker();profileDialog('Seu perfil','Sua identificação nos registros da empresa.',`<div class="profile-hero">${profileAvatar(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.title||'Equipe da empresa')}</p></div></div><div class="profile-options">${profileButton('edit',icon('user')+' Editar nome e foto')}${profileButton('picker',icon('grid')+' Trocar pessoa')}${profileButton('create',icon('plus')+' Criar outro perfil')}${profileButton('leave','Sair deste perfil neste aparelho')}</div><p class="profile-footnote profile-identity-note">Os perfis identificam quem faz os registros na LAN. Esta versão não usa senha nem limita o acesso de outros perfis à frota.</p>`)}
async function prepareProfilePhoto(file){if(!file)return '';if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Escolha uma foto JPG, PNG ou WebP.');if(file.size>8*1024*1024)throw Error('A foto precisa ter até 8 MB.');const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler a foto.'));reader.readAsDataURL(file)});const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Não foi possível abrir a foto.'));img.src=raw});const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Este navegador não conseguiu preparar a foto.');ctx.fillStyle='#f5f1e9';ctx.fillRect(0,0,256,256);const side=Math.min(image.width,image.height);ctx.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,256,256);const photo=canvas.toDataURL('image/jpeg',0.84);if(photo.length>200000)throw Error('Escolha uma foto menor.');return photo}
function editProfile(create=false){if(!requireProfiles())return;const existing=create?null:currentProfile();if(!create&&!existing)return openProfilePicker();modal(create?'Criar meu perfil':'Editar meu perfil','Seu nome e sua foto acompanham seus registros.',`<div class="profile-preview">${profileAvatar(existing)}<p class="help">Sem foto, o Nova Aliança usa as iniciais do seu nome.<br>Você pode adicionar uma foto quando quiser.</p></div>${field('profileName','Nome completo','text',existing?.name||'','required maxlength="80" autocomplete="name"',true)}${field('profileTitle','Função na empresa (opcional)','text',existing?.title||'','maxlength="80" placeholder="Ex.: Gerente, proprietário, motorista"',true)}<label class="full">Foto de perfil (opcional)<input type="file" name="profilePhoto" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG ou WebP, até 8 MB. A foto será ajustada ao perfil.</small></label>${existing?.photo?'<label class="check full"><input name="removePhoto" type="checkbox">Usar minhas iniciais e remover a foto</label>':''}<p class="profile-footnote">A função é uma identificação na equipe; ela não altera permissões de acesso nesta versão.</p>`,async(f,form)=>{if(form.dataset.preparing==='1')return;form.dataset.preparing='1';try{const name=String(f.get('profileName')).trim().replace(/\s+/g,' '),title=String(f.get('profileTitle')).trim();if(!name)throw Error('Informe seu nome.');if((state.profiles||[]).some(p=>p.id!==existing?.id&&p.name.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))throw Error('Já existe um perfil com esse nome. Use Trocar pessoa ou acrescente um sobrenome.');const file=form.elements.profilePhoto.files[0];let photo=existing?.photo||'';if(f.get('removePhoto'))photo='';if(file)photo=await prepareProfilePhoto(file);if(!document.getElementById('modal').open)return;const p=existing||{id:uid(),createdAt:new Date().toISOString()};Object.assign(p,{name,title,photo,updatedAt:new Date().toISOString()});state.profiles=state.profiles||[];if(!existing)state.profiles.push(p);activeProfileId=p.id;try{localStorage.setItem(PROFILE_KEY,p.id)}catch{}await commit(create?'Perfil criado. Você está usando o Nova Aliança como '+name+'.':'Perfil atualizado.');}finally{delete form.dataset.preparing}},create?'Criar perfil':'Salvar perfil')}
function ensureProfileChoice(){if(sharedSupportsProfiles&&!currentProfile()&&!profilePrompted){profilePrompted=true;openProfilePicker()}}
function requireActiveProfile(){if(currentProfile())return true;openProfilePicker();return false}
function teamView(){const people=state.profiles||[];return `<section class="panel"><div class="team-intro"><div><h2>Pessoas da empresa</h2><p class="help">${people.length} perfil(is). Uma única frota compartilhada.</p></div>${profileButton('create',icon('plus')+' Criar perfil','',true)}</div><div class="profile-list">${people.map(p=>`<button class="profile-row ${p.id===activeProfileId?'selected':''}" type="button" data-profile-action="select" data-id="${esc(p.id)}">${profileAvatar(p)}<span class="person-info"><strong>${esc(p.name)}</strong><small>${esc(p.title||'Equipe da empresa')}</small></span>${p.id===activeProfileId?'<span class="tag green">Você</span>':icon('arrow')}</button>`).join('')}</div><p class="help">Nome, foto e identificação são individuais. Veículos, documentos, manutenção e abastecimentos pertencem à empresa.</p></section>`}
document.addEventListener('click',e=>{const target=e.target.closest('[data-profile-action]');if(!target||saving)return;switch(target.dataset.profileAction){case'menu':return openProfileMenu();case'picker':return openProfilePicker();case'create':return editProfile(true);case'edit':return editProfile(false);case'select':return selectProfile(target.dataset.id);case'leave':selectProfile('');return openProfilePicker()}});
